/* updateBuyerMdAmUserInfoPop */ UPDATE ICOMLUSR SET USER_NAME_LOC = #{st_user_name_loc}, USER_NAME_ENG = #{st_user_name_eng}, LANG = #{st_lang}, EMAIL = #{st_email}, USER_TYPE = CASE WHEN #{st_user_type} = 'A' AND #{change_user_type} = 'U' THEN #{change_user_type} ELSE #{st_user_type} END , CHANGE_USER_TYPE = #{change_user_type}, COUNTRY = #{st_country_code}, CITY = #{st_city_code}, ZIP_CODE = #{st_zip_code}, ADDRESS_LOC = #{st_address} || ' ' || #{st_address_dt}, ZIP_KEY = #{st_zip_key}, ADDRESS_LOC1 = #{st_address}, ADDRESS_LOC2 = #{st_address_dt}, MOBILE_PHONE = #{st_mobile_phone}, PHONE_NUMBER = #{st_phone_number}, FAX_NUMBER = #{st_fax_number}, ROW_CNT = #{st_row_cnt}, IMG_VIEW_FLAG = #{st_img_view_flag}, SMS_RECV_FLAG = #{st_sms_recv_flag}, MAIL_RECV_FLAG = #{st_mail_recv_flag}, DEPARTMENT = #{st_department}, POSITION = #{st_position}, PURCHASE_DEPT = #{st_purchase_dept}, PERSON_AUTHOR = NVL(#{st_person_author},PERSON_AUTHOR), USER_GROUP = NVL(#{st_user_group},USER_GROUP), DELY_TO_LOCATION = #{st_dely_to_location}, STATUS = #{st_status}, LEGACY_USER_ID = #{st_legacy_user_id}, MAIL_RECV_CHOICE = #{st_mail_recv}
,TWO_FACTOR_YN = #{st_two_factor_flag} ,TWO_FACTOR_DATE = SYSDATE
,CHG_INFO_PWD_YN = #{st_chg_info_pwd_flag} ,CHG_INFO_PWD_DATE = SYSDATE
WHERE USER_ID = #{st_user_id} AND COM_CODE = #{st_com_code}
